#import <UIKit/UIKit.h>
@interface ProbeVC:UIViewController @end
@implementation ProbeVC
-(UIInterfaceOrientationMask)supportedInterfaceOrientations { return UIInterfaceOrientationMaskPortrait|UIInterfaceOrientationMaskLandscapeLeft|UIInterfaceOrientationMaskLandscapeRight; }
-(void)viewDidLoad { [super viewDidLoad]; self.view.backgroundColor=UIColor.systemBackgroundColor; UILabel *label=[UILabel new];label.text=@"Duo orientation control";label.accessibilityIdentifier=@"orientation-probe-title";label.textAlignment=NSTextAlignmentCenter;label.frame=self.view.bounds;label.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;[self.view addSubview:label]; }
-(void)viewDidLayoutSubviews { [super viewDidLayoutSubviews]; UIWindowScene *s=self.view.window.windowScene; if(!s)return; NSDictionary *data=@{@"at":@([NSDate date].timeIntervalSince1970),@"interface":@(s.interfaceOrientation),@"physical":@(UIDevice.currentDevice.orientation),@"width":@(self.view.bounds.size.width),@"height":@(self.view.bounds.size.height),@"supported":@([self supportedInterfaceOrientations])};NSData *j=[NSJSONSerialization dataWithJSONObject:data options:NSJSONWritingPrettyPrinted error:nil];NSURL *dir=[NSFileManager.defaultManager URLsForDirectory:NSDocumentDirectory inDomains:NSUserDomainMask].firstObject;[j writeToURL:[dir URLByAppendingPathComponent:@"state.json"] atomically:YES]; }
@end
@interface ProbeScene:NSObject<UIWindowSceneDelegate> @property(nonatomic,strong)UIWindow *window; @end
@implementation ProbeScene
-(void)scene:(UIScene *)scene willConnectToSession:(UISceneSession *)session options:(UISceneConnectionOptions *)options { self.window=[[UIWindow alloc]initWithWindowScene:(UIWindowScene *)scene];self.window.rootViewController=[ProbeVC new];[self.window makeKeyAndVisible]; }
@end
@interface ProbeApp:NSObject<UIApplicationDelegate> @end
@implementation ProbeApp
-(UISceneConfiguration *)application:(UIApplication *)app configurationForConnectingSceneSession:(UISceneSession *)session options:(UISceneConnectionOptions *)options { UISceneConfiguration *c=[[UISceneConfiguration alloc]initWithName:@"Probe" sessionRole:session.role];c.delegateClass=ProbeScene.class;return c; }
@end
int main(int argc,char **argv) { @autoreleasepool { return UIApplicationMain(argc,argv,nil,NSStringFromClass(ProbeApp.class)); } }
